+package com.example;
+
+import com.microsoft.playwright.Browser;
+import com.microsoft.playwright.BrowserType;
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.Playwright;
+import com.microsoft.playwright.options.AriaRole;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT,
+        properties = {"vaadin.productionMode=true", "vaadin.launch-browser=false"})
+class ContactBrowserTest {
+    static {
+        // Serve Vaadin's cached bundle for this test without running npm or a frontend build.
+        try {
+            var repository = java.nio.file.Path.of(System.getProperty("maven.repo.local",
+                    System.getProperty("user.home") + "/.m2/repository"));
+            var bundle = repository.resolve("com/vaadin/vaadin-prod-bundle/25.3.2/vaadin-prod-bundle-25.3.2.jar");
+            var output = java.nio.file.Path.of(ContactBrowserTest.class.getProtectionDomain()
+                    .getCodeSource().getLocation().toURI()).resolve("META-INF/VAADIN/webapp");
+            try (var jar = new java.util.jar.JarFile(bundle.toFile())) {
+                var entries = jar.entries();
+                while (entries.hasMoreElements()) {
+                    var entry = entries.nextElement();
+                    String prefix = "vaadin-prod-bundle/webapp/";
+                    if (!entry.isDirectory() && entry.getName().startsWith(prefix)) {
+                        var destination = output.resolve(entry.getName().substring(prefix.length()));
+                        java.nio.file.Files.createDirectories(destination.getParent());
+                        try (var input = jar.getInputStream(entry)) {
+                            java.nio.file.Files.copy(input, destination, java.nio.file.StandardCopyOption.REPLACE_EXISTING);
+                        }
+                    }
+                }
+            }
+        } catch (Exception exception) {
+            throw new ExceptionInInitializerError(exception);
+        }
+    }
+
+    @LocalServerPort
+    private int port;
+
+    @Test
+    void realBrowserValidatesSubmitsWithEnterAndProtectsDraft() {
+        try (Playwright playwright = Playwright.create();
+                Browser browser = playwright.chromium().launch(new BrowserType.LaunchOptions()
+                        .setHeadless(true).setArgs(java.util.List.of("--no-sandbox")))) {
+            Page page = browser.newPage();
+            page.navigate("http://localhost:" + port + "/contact");
+            var send = page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Send").setExact(true));
+            assertThat(send).isEnabled();
+            send.click();
+            assertThat(page.getByText("Name is required", new Page.GetByTextOptions().setExact(true))).isVisible();
+            assertThat(page.getByText("Give an e-mail address or a phone number")).isVisible();
+            page.getByLabel("Name", new Page.GetByLabelOptions().setExact(true)).fill("Browser sender");
+            page.getByLabel("Email", new Page.GetByLabelOptions().setExact(true)).fill("sender@example.com");
+            page.getByLabel("Message", new Page.GetByLabelOptions().setExact(true)).fill("Browser message");
+            page.getByLabel("Name", new Page.GetByLabelOptions().setExact(true)).press("Enter");
+            assertThat(page.getByText("Message sent", new Page.GetByTextOptions().setExact(true))).isVisible();
+            assertThat(send).isDisabled();
+            assertThat(page.getByLabel("Message", new Page.GetByLabelOptions().setExact(true))).isEmpty();
+            page.getByLabel("Phone", new Page.GetByLabelOptions().setExact(true)).fill("Draft phone");
+            assertThat(send).isEnabled();
+            page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+            page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing")).click();
+            assertThat(page.getByLabel("Phone", new Page.GetByLabelOptions().setExact(true))).hasValue("Draft phone");
+            page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+            page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Discard").setExact(true)).click();
+            assertThat(page.getByRole(AriaRole.HEADING,
+                    new Page.GetByRoleOptions().setName("About").setExact(true))).isVisible();
+            page.navigate("http://localhost:" + port + "/contact");
+            assertThat(page.getByText("Browser message", new Page.GetByTextOptions().setExact(true))).isVisible();
+        }
+    }
+}
